#!/usr/bin/env bash
# ═══════════════════════════════════════════════════════════════
# SITA OS — iOS Release Build Pipeline
# Phase 12 — produces a signed IPA ready for App Store submission.
# Pre-flights ios/ existence and bundle ID before xcodebuild.
# ═══════════════════════════════════════════════════════════════
set -euo pipefail

echo "▶ SITA OS — iOS release build"

# ── 0. Pre-flight: ios/ tree must exist (generated by ios-bootstrap.yml) ──
if [ ! -d "ios/App/App.xcworkspace" ]; then
  echo ""
  echo "✘ ios/App/App.xcworkspace not found."
  echo ""
  echo "  The native iOS project hasn't been generated yet. Run the bootstrap first:"
  echo "    Cloud (recommended): GitHub Actions → 'iOS · Bootstrap Native Runtime' → Run workflow"
  echo "    Local Mac:           bash scripts/ios/bootstrap.sh"
  echo ""
  echo "  See docs/ios/IOS_NATIVE_RUNTIME.md for details."
  exit 2
fi

# ── 0b. Pre-flight: hardened templates present ───────────────────
for f in "ios/App/App/Info.plist" "ios/App/App/App.entitlements" "ios/App/App/PrivacyInfo.xcprivacy"; do
  if [ ! -f "$f" ]; then
    echo "✘ Missing hardened file: $f"
    echo "  Re-run the iOS bootstrap to overlay ios-templates/."
    exit 2
  fi
done

# ── 1. Validate signing environment ─────────────────────────────
required_vars=(
  "IOS_TEAM_ID"
  "IOS_BUNDLE_ID"
  "IOS_PROVISIONING_PROFILE"
  "IOS_SIGNING_CERTIFICATE"
)
missing=0
for v in "${required_vars[@]}"; do
  if [ -z "${!v:-}" ]; then
    echo "  ✘ missing env: $v"
    missing=1
  fi
done
if [ "$missing" = "1" ]; then
  echo ""
  echo "iOS release blocked: signing env vars missing."
  echo "Set IOS_TEAM_ID, IOS_BUNDLE_ID, IOS_PROVISIONING_PROFILE, IOS_SIGNING_CERTIFICATE."
  exit 2
fi

# ── 1b. Reject placeholder bundle ID for signed builds ─────────
if [[ "$IOS_BUNDLE_ID" == "app.lovable."* ]]; then
  echo "✘ IOS_BUNDLE_ID is still the Lovable placeholder ('$IOS_BUNDLE_ID')."
  echo "  Set a real reverse-DNS bundle ID registered in your Apple Developer account."
  echo "  Example: com.sita.os"
  exit 2
fi

# ── 2. Build web bundle ─────────────────────────────────────────
echo "▶ Building web bundle"
npm run build

# ── 3. Sync Capacitor → iOS ─────────────────────────────────────
echo "▶ Syncing Capacitor"
npx cap sync ios

# ── 4. Archive + export IPA ─────────────────────────────────────
ARCHIVE_PATH="${ARCHIVE_PATH:-build/ios/SITA-OS.xcarchive}"
EXPORT_PATH="${EXPORT_PATH:-build/ios/ipa}"
SCHEME="${IOS_SCHEME:-App}"

echo "▶ Archiving Xcode workspace"
xcodebuild \
  -workspace ios/App/App.xcworkspace \
  -scheme "$SCHEME" \
  -configuration Release \
  -destination "generic/platform=iOS" \
  -archivePath "$ARCHIVE_PATH" \
  DEVELOPMENT_TEAM="$IOS_TEAM_ID" \
  PRODUCT_BUNDLE_IDENTIFIER="$IOS_BUNDLE_ID" \
  archive

echo "▶ Exporting IPA"
xcodebuild \
  -exportArchive \
  -archivePath "$ARCHIVE_PATH" \
  -exportPath "$EXPORT_PATH" \
  -exportOptionsPlist scripts/release/ios/exportOptions.plist

echo "✓ iOS build complete → $EXPORT_PATH"
